<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Http\Resources\BookingResource;use App\Models\Booking;use App\Services\BookingService;use Illuminate\Http\Request;
class BookingController extends Controller { public function __construct(private BookingService $service){} public function store(Request $r){$d=$r->validate(['vehicle_id'=>'required|exists:vehicles,id','pickup_location'=>'required|string|max:120','dropoff_location'=>'required|string|max:120','pickup_date'=>'required|date','return_date'=>'required|date','pickup_time'=>'required|date_format:H:i','return_time'=>'required|date_format:H:i','rental_type'=>'required|in:self_drive,with_driver','full_name'=>'required|string|max:150','phone'=>'required|string|max:40','email'=>'nullable|email|max:190','cnic'=>'nullable|string|max:60','address'=>'nullable|string|max:500','notes'=>'nullable|string|max:2000']);$booking=$this->service->create($d);return (new BookingResource($booking))->response()->setStatusCode(201);} public function byReference(string $reference){$b=Booking::with(['vehicle','pickupLocation','dropoffLocation'])->where('reference',$reference)->firstOrFail();return response()->json(['data'=>['reference'=>$b->reference,'vehicle'=>['id'=>$b->vehicle?->id,'name'=>$b->vehicle?->name,'slug'=>$b->vehicle?->slug],'pickup_location'=>$b->pickupLocation?->name?:$b->pickup_location_text,'dropoff_location'=>$b->dropoffLocation?->name?:$b->dropoff_location_text,'pickup_at'=>$b->pickup_at?->toIso8601String(),'return_at'=>$b->return_at?->toIso8601String(),'duration_days'=>$b->duration_days,'total_price'=>$b->total_price,'payment_status'=>$b->payment_status,'status'=>$b->status]]);} }
